// Ограничивает длину строки при неотрицательном лимите.
//
// Параметры:
//  Текст - Строка - исходное значение
//  Лимит - Число - неотрицательная максимальная длина
//
// Возвращаемое значение:
//  Строка - результат ограничения
//
Функция ОграничитьДлину(Текст, Лимит) Экспорт

	Возврат Лев(Текст, Лимит);

КонецФункции

source_files.РасчетыЗаказов.bsl:
// Вычисляет сумму после скидки клиента.
//
// Параметры:
//  Сумма - Число - сумма до скидки
//  Клиент - Строка - ключ клиента
//
// Возвращаемое значение:
//  Число - сумма после скидки
//
Функция СуммаСоСкидкой(Сумма, Клиент) Экспорт

	Скидка = НастройкиКлиентов.ПроцентСкидки(Клиент);

	Возврат Сумма * (1 - Скидка / 100);

КонецФункции

