&Вместо("ЗаписатьСобытие")
Процедура ЮТЗаписатьСобытие(Ключ)

	ПараметрыМетода     = Мокито.МассивПараметров(Ключ);
	ПрерватьВыполнение = Ложь;

	МокитоПерехват.АнализВызова(
		ОбработкаСообщений, "ЗаписатьСобытие", ПараметрыМетода, ПрерватьВыполнение);

	Если НЕ ПрерватьВыполнение Тогда
		ПродолжитьВызов(Ключ);
	КонецЕсли;

КонецПроцедуры
